program:
phase("Scan")

def scanretry(shard, lens, sampleid):
    out = scan(shard, lens, sample=sampleid)
    if out is None:
        out = scan(shard, lens, sample=sampleid + 100)
    if out is None:
        out = []
    return out

def checkretry(batch, sampleid):
    out = check(batch, sample=sampleid)
    if out is None:
        out = check(batch, sample=sampleid + 100)
    if out is None:
        out = []
    return out

shardlist = list(shards(100000))
roundlenses = [
    "general", "logic", "boundaries", "state",
    "general", "logic", "boundaries", "state",
    "general", "logic", "boundaries", "state",
    "general", "logic"
]

allfindings = []
log(f"Scanning {len(shardlist)} shards")

for sampleid, lens in enumerate(roundlenses):
    found = flatten(parallel([
        lambda s=s, l=lens, r=sampleid: scanretry(s, l, r)
        for s in shardlist
    ]))
    allfindings.extend(found)
    log(f"Round {sampleid + 1} lens {lens}: {len(found)} findings")

candidates = dedupe(allfindings)
log(f"{len(candidates)} unique candidates")

phase("Verify")
if len(candidates) == 0:
    confirmed = []
else:
    batchlist = list(batches(candidates, 8))
    verdicts = flatten(parallel([
        lambda b=b, k=k: checkretry(b, k)
        for b in batchlist
        for k in range(3)
    ]))
    log(f"{len(verdicts)} verdicts from {len(batchlist)} batches")
    confirmed = vote(candidates, verdicts, need=2)
    log(f"{len(confirmed)} confirmed after vote")

phase("Report")
if len(confirmed) == 0:
    result = {"bugs": []}
else:
    final = report(confirmed)
    if final is None:
        final = {"bugs": confirmed}
    final.setdefault("bugs", confirmed)
    result = final
